-- =============================================
-- PROCEDIMIENTOS ALMACENADOS
-- =============================================

-- 1. Registrar Pago
CREATE OR REPLACE PROCEDURE registrar_pago(
    p_cliente_id INTEGER,
    p_monto DECIMAL(10,2),
    p_metodo VARCHAR(50)
)
LANGUAGE plpgsql
AS $$
BEGIN
    INSERT INTO pago (cliente_id, monto, metodo_pago, fecha_pago, estado)
    VALUES (p_cliente_id, p_monto, p_metodo, CURRENT_TIMESTAMP, 'Completado');

    UPDATE cliente 
    SET saldo = saldo - p_monto
    WHERE id = p_cliente_id;

    RAISE NOTICE 'Pago registrado: $% para cliente %', p_monto, p_cliente_id;
END;
$$;

-- 2. Generar Reporte de Ventas
CREATE OR REPLACE PROCEDURE generar_reporte_ventas(
    p_fecha_inicio DATE,
    p_fecha_fin DATE
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_total_ventas DECIMAL(10,2);
    v_numero_ventas INTEGER;
BEGIN
    SELECT COUNT(*), COALESCE(SUM(total), 0)
    INTO v_numero_ventas, v_total_ventas
    FROM factura
    WHERE fecha_factura BETWEEN p_fecha_inicio AND p_fecha_fin
        AND estado = 'Pagada';

    RAISE NOTICE 'Reporte de ventas: % ventas por $%', v_numero_ventas, v_total_ventas;
END;
$$;

-- 3. Actualizar Stock
CREATE OR REPLACE PROCEDURE actualizar_stock(
    p_producto_id INTEGER,
    p_cantidad INTEGER,
    p_tipo VARCHAR(20)
)
LANGUAGE plpgsql
AS $$
BEGIN
    IF p_tipo = 'Entrada' THEN
        UPDATE producto SET stock_actual = stock_actual + p_cantidad WHERE id = p_producto_id;
    ELSIF p_tipo = 'Salida' THEN
        UPDATE producto SET stock_actual = stock_actual - p_cantidad WHERE id = p_producto_id;
    END IF;

    INSERT INTO movimiento_inventario (producto_id, tipo_movimiento, cantidad, fecha_movimiento)
    VALUES (p_producto_id, p_tipo, p_cantidad, CURRENT_TIMESTAMP);
END;
$$;

-- 4. Calcular Total Pedido
CREATE OR REPLACE FUNCTION calcular_total_pedido(
    p_pedido_id INTEGER
)
RETURNS DECIMAL(10,2)
LANGUAGE plpgsql
AS $$
DECLARE
    v_total DECIMAL(10,2);
BEGIN
    SELECT SUM(cantidad * precio_unitario)
    INTO v_total
    FROM detalle_pedido
    WHERE pedido_id = p_pedido_id;

    RETURN COALESCE(v_total, 0);
END;
$$;

-- =============================================
-- Trigger: trg_validar_stock_salida
-- Descripción: Valida que haya stock suficiente antes de registrar una salida
-- =============================================

-- Función del trigger
CREATE OR REPLACE FUNCTION fn_validar_stock_salida()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
DECLARE
    v_stock_actual INTEGER;
    v_producto_nombre VARCHAR(100);
BEGIN
    -- Solo validar para salidas
    IF NEW.tipo_movimiento = 'Salida' THEN
        -- Obtener stock actual del producto
        SELECT stock_actual, nombre INTO v_stock_actual, v_producto_nombre
        FROM producto WHERE id = NEW.producto_id;

        -- Validar que el producto exista
        IF v_stock_actual IS NULL THEN
            RAISE EXCEPTION 'Producto no encontrado: %', NEW.producto_id;
        END IF;

        -- Validar stock suficiente
        IF v_stock_actual < NEW.cantidad THEN
            RAISE EXCEPTION 'Stock insuficiente para %. Stock actual: %, Cantidad solicitada: %',
                v_producto_nombre, v_stock_actual, NEW.cantidad;
        END IF;

        -- Actualizar stock del producto
        UPDATE producto 
        SET stock_actual = stock_actual - NEW.cantidad,
            updated_at = CURRENT_TIMESTAMP
        WHERE id = NEW.producto_id;

        -- Registrar el stock resultante en el movimiento
        NEW.stock_resultante := v_stock_actual - NEW.cantidad;
    END IF;

    RETURN NEW;
END;
$$;

-- Crear el trigger
CREATE TRIGGER trg_validar_stock_salida
BEFORE INSERT ON movimiento_inventario
FOR EACH ROW
EXECUTE FUNCTION fn_validar_stock_salida();

